import { getInitializedSimulationRuntime } from '/src/ui/runtime/simulationRuntime'
import { Tokens } from '/src/core/providers/tokens'
import { GpuTimer } from '/tests/browser/gpuTimer'
import { unculledVertexReference } from '/tests/asteroidImpostors/unculledVertexReference'
import { state } from './profile.browser'

const stats = (samples: number[]) => {
  const sorted = samples.slice().sort((a, b) => a - b)
  return { count: samples.length, p50: sorted[Math.ceil(samples.length * .5) - 1], p95: sorted[Math.ceil(samples.length * .95) - 1], max: sorted.at(-1), samples }
}
