      if (system.constructor.name !== 'AsteroidRingSystem') return
      for (let p = system; p; p = p.parent) if (!p.visible) return
      const source = system.pool.billboardMesh
      if (!source.visible || !source.count) return
      metadata.push({ actor: system.model?.getAttribute('id'), name: source.name, count: source.count, ready: source.material.uniforms.uImpostorReady?.value, defines: source.material.defines })
      const uniforms: any = {}
      for (const [name, uniform] of Object.entries(source.material.uniforms) as any) uniforms[name] = uniform.value?.isTexture ? { value: uniform.value } : UniformsUtils.clone({ uniform }).uniform
