    if (!metadata.length || metadata.some(r => r.ready !== 1)) throw new Error('Atlas L1 missing')
    const render = (mode: number) => { renderer.setRenderTarget(target); renderer.setClearColor(0, 0); renderer.clear(); renderer.render(scenes[mode], camera) }
    const read = (buffer: WebGLRenderTarget) => { const data = new Float32Array(width * height * 4); renderer.readRenderTargetPixels(buffer, 0, 0, width, height, data); return data }
    const pixels = (mode: number) => {
      render(mode); const color = read(target)
