        baseline: first[0], production: first[1], baselineRepeat: repeat[0], productionRepeat: repeat[1] }
      rows.push(row)
      console.info('L1_CONFIRM', JSON.stringify({ yaw, image, depth, baseline: row.baseline.p50, production: row.production.p50, baselineRepeat: row.baselineRepeat.p50, productionRepeat: row.productionRepeat.p50 }))
    }
