import { AdditiveBlending, Box3, Color, FloatType, Frustum, InstancedMesh, Matrix4, NoBlending, Scene, ShaderMaterial, UniformsUtils, Vector3, WebGLRenderTarget } from 'three'
import { getInitializedSimulationRuntime } from '/src/ui/runtime/simulationRuntime'
import { Tokens } from '/src/core/providers/tokens'
import { GpuTimer } from '/tests/browser/gpuTimer'
import { state } from './profile.browser'

const stats = (values: number[]) => {
  const sorted = values.slice().sort((a, b) => a - b)
  return { count: values.length, p50: sorted[Math.ceil(values.length * .5) - 1], p95: sorted[Math.ceil(values.length * .95) - 1], max: sorted.at(-1), sum: values.reduce((a, b) => a + b, 0) }
}
const vertexAnchor = 'vec2 halfSize = extent.xy;'
// Conservative view-space AABB rejection. Diagnostic: side planes only, so
// fragment-written/logarithmic depth and near/far clipping are unaffected.
export const cullOffscreen = (source: string) => {
  if (!source.includes(vertexAnchor)) throw new Error('Atlas bound anchor absent')
  return source.replace(vertexAnchor, `
    vec4 clipCenter = projectionMatrix * vec4(center, 1.0);
    vec3 px = vec3(projectionMatrix[0][0], projectionMatrix[1][0], projectionMatrix[2][0]);
    vec3 py = vec3(projectionMatrix[0][1], projectionMatrix[1][1], projectionMatrix[2][1]);
    vec3 pw = vec3(projectionMatrix[0][3], projectionMatrix[1][3], projectionMatrix[2][3]);
    vec3 captureExtent = extent * 1.5;
    if (clipCenter.x + clipCenter.w < -dot(abs(px + pw), captureExtent) ||
        clipCenter.w - clipCenter.x < -dot(abs(pw - px), captureExtent) ||
        clipCenter.y + clipCenter.w < -dot(abs(py + pw), captureExtent) ||
        clipCenter.w - clipCenter.y < -dot(abs(pw - py), captureExtent)) {
      gl_Position = vec4(2.0, 2.0, 2.0, 1.0); return;
    }
    ${vertexAnchor}`)
}

export async function diagnoseL1() {
  const c = getInitializedSimulationRuntime()!.container
  const engine = c.get(Tokens.Engine), renderer = c.get(Tokens.Renderer), camera = c.get(Tokens.Camera)
  engine.stop(); engine.renderFrame()
