  const savedTarget = renderer.getRenderTarget(), savedColor = renderer.getClearColor(new Color()), savedAlpha = renderer.getClearAlpha()
  const width = renderer.domElement.width, height = renderer.domElement.height
  const target = new WebGLRenderTarget(width, height, { type: FloatType })
  const resources: any[] = [target], sources: any[] = [], variants: Record<string, Scene> = {}
  const metadata: any[] = [], rows: any[] = []
  try {
    c.get(Tokens.Scene).traverse((system: any) => {
      if (system.constructor.name !== 'AsteroidRingSystem') return
      for (let p = system; p; p = p.parent) if (!p.visible) return
      const source = system.pool.billboardMesh
      if (!source.visible || !source.count) return
      sources.push(source)
      metadata.push({ name: source.name, id: source.id, parent: system.model?.getAttribute('id'), count: source.count,
        ready: source.material.uniforms.uImpostorReady?.value, defines: source.material.defines,
        maxDistance: source.material.uniforms.uMaxDistance.value, physicalSize: source.material.uniforms.uImpostorPhysicalSize?.value,
        halfExtents: Array.from(source.material.uniforms.uImpostorHalfExtents?.value ?? []) })
      for (const name of ['original', 'culled', 'flat', 'flatCulled', 'coverage', 'coverageCulled']) {
        const material = new ShaderMaterial()
        material.copy(Object.assign(Object.create(source.material), { uniforms: {} }))
        material.uniforms = {}
        for (const [key, uniform] of Object.entries(source.material.uniforms) as any) {
          material.uniforms[key] = uniform.value?.isTexture ? { value: uniform.value } : UniformsUtils.clone({ uniform }).uniform
        }
        if (name === 'culled' || name.endsWith('Culled')) material.vertexShader = cullOffscreen(material.vertexShader)
        if (name.startsWith('flat') || name.startsWith('coverage')) {
          material.fragmentShader = 'void main() { gl_FragColor = vec4(1.0); }'
