        const mesh = new InstancedMesh(source.geometry, material, source.count)
        mesh.instanceMatrix.array.set(source.instanceMatrix.array.subarray(0, source.count * 16))
        mesh.count = source.count; mesh.frustumCulled = false; mesh.matrixAutoUpdate = false
        mesh.matrix.copy(source.matrixWorld)
        ;(variants[name] ??= new Scene()).add(mesh)
