    })
    if (!sources.length || metadata.some(r => r.ready !== 1)) throw new Error('Atlas L1 missing/not ready')
    const render = (name: string) => {
      renderer.setRenderTarget(target); renderer.setClearColor(0, 0); renderer.clear(); renderer.render(variants[name], camera)
    }
    const read = () => { const pixels = new Float32Array(target.width * target.height * 4); renderer.readRenderTargetPixels(target, 0, 0, target.width, target.height, pixels); return pixels }
