    for (const yaw of [0, Math.PI / 4]) {
      camera.quaternion.copy(originalOrientation); camera.rotateY(yaw); camera.updateMatrixWorld(true)
      const geometryStats = sources.map(source => {
        const mv = camera.matrixWorldInverse.clone().multiply(source.matrixWorld), projection = camera.projectionMatrix
        const frustum = new Frustum().setFromProjectionMatrix(projection), matrix = new Matrix4(), a = new Matrix4(), center = new Vector3(), extent = new Vector3()
        const origin = source.geometry.getAttribute('instanceOrigin'), detail = source.geometry.getAttribute('instanceDetailEnd'), fade = source.geometry.getAttribute('instanceFade')
