          const h = u.uImpostorHalfExtents.value[slot] * u.uImpostorPhysicalSize.value
          a.multiplyMatrices(mv, matrix)
          const e = a.elements
          extent.set(Math.hypot(e[0], e[4], e[8]), Math.hypot(e[1], e[5], e[9]), Math.hypot(e[2], e[6], e[10])).multiplyScalar(h)
          const intersects = frustum.intersectsBox(new Box3(center.clone().sub(extent), center.clone().add(extent)))
          if (intersects) inBounds++
          const depth = -center.z
          if (depth <= camera.near || depth >= camera.far) { behind++; continue }
          const half = extent.clone()
          half.x = (extent.x + Math.abs(center.x) * extent.z / Math.max(depth, 1e-6)) * Math.max(depth, 1e-6) / Math.max(depth - extent.z, 1e-6)
          half.y = (extent.y + Math.abs(center.y) * extent.z / Math.max(depth, 1e-6)) * Math.max(depth, 1e-6) / Math.max(depth - extent.z, 1e-6)
