    }
    if (renderer.getContext().getError()) throw new Error('L1 WebGL error')
    return { snapshot, metadata, rows }
  } finally {
    for (const resource of resources) resource.dispose()
    renderer.setRenderTarget(savedTarget); renderer.setClearColor(savedColor, savedAlpha)
    camera.quaternion.copy(originalOrientation); camera.updateMatrixWorld(true); engine.start()
  }
}

