import { Tokens } from '/src/core/providers/tokens'
import { Vector3 } from 'three'
import { profile } from './shape-profile.browser'

const stats = (values: number[]) => {
  const sorted = values.slice().sort((a, b) => a - b)
  return { count: values.length, p50: sorted[Math.ceil(values.length * .5) - 1], p95: sorted[Math.ceil(values.length * .95) - 1], max: sorted.at(-1), mean: values.reduce((a, b) => a + b, 0) / values.length }
}
export async function movingShape() {
  const c = getInitializedSimulationRuntime()!.container, engine = c.get(Tokens.Engine), camera = c.get(Tokens.Camera)
  const position = camera.position.clone(), orientation = camera.quaternion.clone(), original = engine.renderFrame
  const direction = new Vector3(1, 0, 0).applyQuaternion(orientation)
  let frame = 0
  engine.renderFrame = function () {
    const progress = Math.min(frame++ / 63, 1)
    camera.position.copy(position).addScaledVector(direction, progress * 2)
    camera.quaternion.copy(orientation); camera.rotateY(progress * Math.PI * 2); camera.updateMatrixWorld(true)
    return original.call(this)
  }
  try {
    const result = await profile(64, 'draws', false)
    const perFrame: Record<string, number[]> = Object.fromEntries(['Near', 'L0', 'L1', 'other', 'total'].map(k => [k, Array(64).fill(0)]))
    for (const [key, samples] of Object.entries(result.gpu)) {
      const frames = result.drawFrameIndices[key]
      if (frames.length !== samples.length) throw new Error('Draw samples lost frame correspondence')
      const group = key.match(/AsteroidPool_(Near|L0|L1)/)?.[1] ?? 'other'
      samples.forEach((ms, i) => { perFrame[group][frames[i]] += ms; perFrame.total[frames[i]] += ms })
    }
    return { ...result, perFrame, groups: Object.fromEntries(Object.entries(perFrame).map(([key, values]) => [key, stats(values)])),
      caveat: 'Sum of native per-draw GPU queries inside RenderPass per engine frame; query overhead is present. Not a paired motion speedup comparison, not entire-frame time.' }
  } finally { engine.renderFrame = original; camera.position.copy(position); camera.quaternion.copy(orientation) }
}
